diff --git a/src/server.js b/src/server.js
index 0969320..f4b6e6e 100644
--- a/src/server.js
+++ b/src/server.js
@@ -3,6 +3,7 @@ import { Router } from './router.js'
 import { Inventory } from './inventory.js'
 import { Cart } from './cart.js'
 import { formatCurrency } from './format.js'
+import { render as renderReport } from './report.js'

 /**
  * Build the request handler. Exported separately so tests can call it without a socket.
@@ -29,6 +30,22 @@ export function createApp(inventory = Inventory.fromFile()) {
     return { status: 200, body: { totalCents: total, total: formatCurrency(total) } }
   })

+  router.get('/reports/inventory', ({ query }) => {
+    const format = query.get('format') ?? 'text'
+    try {
+      const body = renderReport(inventory.list(), format)
+      const ct =
+        format === 'markdown'
+          ? 'text/markdown; charset=utf-8'
+          : format === 'csv'
+          ? 'text/csv; charset=utf-8'
+          : 'text/plain; charset=utf-8'
+      return { status: 200, body, headers: { 'content-type': ct } }
+    } catch (err) {
+      return { status: 400, body: { error: err.message } }
+    }
+  })
+
   return async function handle(req) {
     const url = new URL(req.url, 'http://localhost')
     const match = router.match(req.method, url.pathname)
@@ -67,6 +84,11 @@ export function startServer(port = Number(process.env.PORT ?? 3000)) {
       return res.end(JSON.stringify({ error: 'Invalid JSON' }))
     }
     const out = await handle({ method: req.method, url: req.url, body })
+    if (typeof out.body === 'string') {
+      const ct = (out.headers && out.headers['content-type']) || 'text/plain; charset=utf-8'
+      res.writeHead(out.status, { 'content-type': ct, ...(out.headers ?? {}) })
+      return res.end(out.body)
+    }
     res.writeHead(out.status, { 'content-type': 'application/json', ...(out.headers ?? {}) })
     res.end(JSON.stringify(out.body))
   })
